import{_ as t,o,c as a,a2 as n}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Latency probe","description":"","frontmatter":{},"headers":[],"relativePath":"guide/latency.md","filePath":"guide/latency.md","lastUpdated":1792973161000}'),r={name:"guide/latency.md"};function s(i,e,d,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="latency-probe" tabindex="-1">Latency probe <a class="header-anchor" href="#latency-probe" aria-label="Permalink to &quot;Latency probe&quot;">​</a></h1><p>This page explains how to measure how fast each provider responds from your network, and how MeetCue uses the result to choose endpoints and compare combinations.</p><h2 id="why-measure" tabindex="-1">Why measure <a class="header-anchor" href="#why-measure" aria-label="Permalink to &quot;Why measure&quot;">​</a></h2><p>The time from the end of a question to the first talking point depends on your network path to each provider, not just on the provider. Many providers offer several endpoints. MeetCue doesn&#39;t assume which one suits you: it measures them and shows only the host name and the measured times.</p><h2 id="run-the-probe" tabindex="-1">Run the probe <a class="header-anchor" href="#run-the-probe" aria-label="Permalink to &quot;Run the probe&quot;">​</a></h2><ol><li>Open <strong>Settings › Providers &amp; cost</strong> and click <strong>Run latency probe</strong>. You can also click the latency figure in the panel footer.</li><li>Optionally enter a <strong>Network label</strong> such as &quot;home&quot; or &quot;office&quot;, so you can compare results from different places later.</li><li>Without API keys, tick <strong>Network only</strong>. It&#39;s free and measures DNS, connection and TLS times for every endpoint.</li><li>With keys, MeetCue shows the expected cost first: about 30 seconds of audio per speech service and about 8 short model calls, a few cents in total. Click <strong>Run the probe</strong> to confirm.</li></ol><h2 id="what-is-measured" tabindex="-1">What is measured <a class="header-anchor" href="#what-is-measured" aria-label="Permalink to &quot;What is measured&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Measurement</th><th>Repeats</th></tr></thead><tbody><tr><td>Network</td><td>DNS lookup, TCP connection and TLS handshake for every endpoint</td><td>5, median</td></tr><tr><td>Speech recognition</td><td>A built-in 9-second recording with Chinese and English, ending in a question, streamed at real-time speed. Start of speech → first partial result, and end of audio → final text</td><td>3</td></tr><tr><td>Models</td><td>A short transcript with the hint prompt. Request → first token, and request → first complete talking point</td><td>1 warm-up, then 3</td></tr></tbody></table><h2 id="read-the-results" tabindex="-1">Read the results <a class="header-anchor" href="#read-the-results" aria-label="Permalink to &quot;Read the results&quot;">​</a></h2><p>Each provider row shows the median and the slowest value. The <strong>Combinations</strong> table estimates the end-to-end delay of every speech and model pairing:</p><blockquote><p>sentence-end wait + recognition + detection + first talking point</p></blockquote><p>and its cost per hour. Sort by fastest, cheapest or balanced, then click <strong>Apply</strong> on the combination you want. Endpoints set to <strong>Auto</strong> switch to the fastest one measured.</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><p>Results are saved in <code>latency-history.json</code> in your settings folder, with the time and network label. Practice mode uses the most recent results to simulate recognition delay.</p><h2 id="live-monitoring" tabindex="-1">Live monitoring <a class="header-anchor" href="#live-monitoring" aria-label="Permalink to &quot;Live monitoring&quot;">​</a></h2><p>During a meeting the footer shows the latency of the last hint, and hovering shows the median. If three questions in a row take more than 2.5 seconds, the panel suggests running the probe again; your network or the fastest endpoint may have changed.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Only your own measurements count. Latency measured from another network or a cloud server says little about yours.</p></div>',17)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
